class Node:
    def __init__(self, value, succeeding=None, previous=None):
        self.value = value
        self.succeeding = succeeding
        self.prev = previous


class LinkedList:
    def __init__(self):
        self.head = None
        self.tail = None
        self.length = 0

    def __len__(self):
        return self.length

    def __iter__(self):
        current_node = self.head
        while current_node:
            yield (current_node.value, current_node.succeeding, current_node.prev)
            current_node = current_node.succeeding

    def delete(self, to_delete):
        if self.length == 0:
            raise ValueError("Value not found")
        found = False
        node = self.head

        for value, succeeding, prev in self:
            if value == to_delete:
                if prev:
                    node.prev.succeeding = succeeding
                else:
                    self.head = succeeding
                if succeeding:
                    node.succeeding.prev = prev
                else:
                    self.tail = prev

                found = True
                self.length -= 1
                break
            node = node.succeeding
        if not found:
            raise ValueError("Value not found")

    def push(self, value):
        new_node = Node(value)
        if not self.head:
            self.head = self.tail = new_node
        else:
            new_node.prev = self.tail
            self.tail.succeeding = new_node
            self.tail = new_node

        self.length += 1

    def pop(self):
        node = self.tail

        if self.length == 0:
            raise IndexError("List is empty")
        if node is None or node.prev is None:
            self.head = self.tail = None
        else:
            self.tail = self.tail.prev
            self.tail.succeeding = None
        self.length -= 1

        return node.value

    def shift(self):
        if self.length == 0:
            raise IndexError("List is empty")
        node = self.head
        if node is None or node.succeeding is None:
            self.head = self.tail = None
        else:
            self.head = self.head.succeeding
            self.head.prev = None
        self.length -= 1

        return node.value

    def unshift(self, value):
        new_node = Node(value)
        if not self.head:
            self.head = self.tail = new_node
        else:
            new_node.succeeding = self.head
            self.head.prev = new_node
            self.head = new_node

        self.length += 1

from typing import Protocol


class Comparable(Protocol):
    def __lt__(self, other: object, /) -> bool: ...


def adaptive_merge_sort[T: Comparable](sequence: list[T]) -> list[T]:
    if len(sequence) < 2:
        return sequence

    aux = sequence[:]
    adaptive_merge_sort_helper(sequence, aux, 0, len(sequence) - 1)
    return sequence


def adaptive_merge_sort_helper[T: Comparable](
    array: list[T], aux: list[T], low: int, high: int
) -> None:
    if high <= low:
        return

    mid = (low + high) // 2

    adaptive_merge_sort_helper(aux, array, low, mid)
    adaptive_merge_sort_helper(aux, array, mid + 1, high)

    if not array[mid + 1] < array[mid]:
        array[low : high + 1] = aux[low : high + 1]
        return

    merge(array, aux, low, mid, high)


def merge[T: Comparable](
    array: list[T], aux: list[T], low: int, mid: int, high: int
) -> None:
    i, j = low, mid + 1

    for k in range(low, high + 1):
        if i > mid or j > high:
            if i > mid:
                aux[k] = array[j]
                j += 1
            else:
                aux[k] = array[i]
                i += 1
        elif not array[j] < array[i]:
            aux[k] = array[i]
            i += 1
        else:
            aux[k] = array[j]
            j += 1

    for k in range(low, high + 1):
        array[k] = aux[k]

from __future__ import annotations

from collections import deque


class Automaton:
    def __init__(self, keywords: list[str]) -> None:
        self.adlist: list[dict] = []
        self.adlist.append(
            {"value": "", "next_states": [], "fail_state": 0, "output": []}
        )

        for keyword in keywords:
            self.add_keyword(keyword)
        self.set_fail_transitions()

    def find_next_state(self, current_state: int, char: str) -> int | None:
        for state in self.adlist[current_state]["next_states"]:
            if char == self.adlist[state]["value"]:
                return state
        return None

    def add_keyword(self, keyword: str) -> None:
        current_state = 0
        for character in keyword:
            next_state = self.find_next_state(current_state, character)
            if next_state is None:
                self.adlist.append(
                    {
                        "value": character,
                        "next_states": [],
                        "fail_state": 0,
                        "output": [],
                    }
                )
                self.adlist[current_state]["next_states"].append(len(self.adlist) - 1)
                current_state = len(self.adlist) - 1
            else:
                current_state = next_state
        self.adlist[current_state]["output"].append(keyword)

    def set_fail_transitions(self) -> None:
        q: deque = deque()
        for node in self.adlist[0]["next_states"]:
            q.append(node)
            self.adlist[node]["fail_state"] = 0
        while q:
            r = q.popleft()
            for child in self.adlist[r]["next_states"]:
                q.append(child)
                state = self.adlist[r]["fail_state"]
                while (
                    self.find_next_state(state, self.adlist[child]["value"]) is None
                    and state != 0
                ):
                    state = self.adlist[state]["fail_state"]
                self.adlist[child]["fail_state"] = self.find_next_state(
                    state, self.adlist[child]["value"]
                )
                if self.adlist[child]["fail_state"] is None:
                    self.adlist[child]["fail_state"] = 0
                self.adlist[child]["output"] = (
                    self.adlist[child]["output"]
                    + self.adlist[self.adlist[child]["fail_state"]]["output"]
                )

    def search_in(self, string: str) -> dict[str, list[int]]:
        """
        >>> A = Automaton(["what", "hat", "ver", "er"])
        >>> A.search_in("whatever, err ... , wherever")
        {'what': [0], 'hat': [1], 'ver': [5, 25], 'er': [6, 10, 22, 26]}
        """
        result: dict = {}  # returns a dict with keywords and list of its occurrences
        current_state = 0
        for i in range(len(string)):
            while (
                self.find_next_state(current_state, string[i]) is None
                and current_state != 0
            ):
                current_state = self.adlist[current_state]["fail_state"]
            next_state = self.find_next_state(current_state, string[i])
            if next_state is None:
                current_state = 0
            else:
                current_state = next_state
                for key in self.adlist[current_state]["output"]:
                    if key not in result:
                        result[key] = []
                    result[key].append(i - len(key) + 1)
        return result


